package com.thesis.geckowifi.eduroam

import java.security.KeyFactory
import java.security.PublicKey
import java.security.spec.X509EncodedKeySpec
import java.util.Base64

/**
 * The key that signs [gecko.realm.SignedRealmRecord]s, pinned at build time
 * like [com.thesis.geckowifi.data.remote.PinnedServerKey]. Generated by
 * `lab/eduroam/make-pki.sh` (lab-secrets/realm/realm-signing.pub.der).
 *
 * Demo shortcut: one key for every realm, standing in for a realm keyspace
 * in the map (docs/eduroam-decisions.md, D6). If the lab PKI is ever
 * regenerated, replace the value below, or every record fails to verify.
 */
object PinnedRealmKey {

    private const val PINNED_PUBLIC_KEY_BASE64 =
        "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEzKTW+8l/kPDNSu0zqfV8IR6lJYyqjKx2CGUdeufzmvmUJicbAwBHS+I5cgQuIciWmayUlPhCTV49ulX05uwtLg=="

    val publicKey: PublicKey by lazy {
        KeyFactory.getInstance("EC").generatePublic(X509EncodedKeySpec(Base64.getDecoder().decode(PINNED_PUBLIC_KEY_BASE64)))
    }
}
